# ── تدقيق محلّيّ قبل الكتابة ──
def _norm(s):  # copy of normalizeArabic (src/server/lib/arabic.ts) as used by the other builders
    s = unicodedata.normalize("NFKC", s)
    s = re.sub("[ً-ْٰـ]", "", s)
    s = re.sub("[أإآٱ]", "ا", s).replace("ة", "ه").replace("ى", "ي").replace("ؤ", "و").replace("ئ", "ي")
    s = "".join(c if (c.isalnum() or c.isspace()) and c != "_" else " " for c in s)
    return re.sub(r"\s+", " ", s.lower()).strip()


def _exact(s):  # engine's exact(): NFC + whitespace collapse
    return re.sub(r"\s+", " ", unicodedata.normalize("NFC", s)).strip()


def _check():
    els = {e["id"]: e["max_points"] for qq in Q for e in qq["rubric_elements"]}
    for qq in Q:
        assert abs(sum(e["max_points"] for e in qq["rubric_elements"]) - qq["rubric_total"]) < 1e-9, qq["id"]
    got = {}
    for s in S:
        p, a, t = s["payload"], s["answer"], s["type"]
        assert s["points"] > 0 and abs(s["points"] * 4 - round(s["points"] * 4)) < 1e-9, s["id"]
        got[s["rubric_element_id"]] = got.get(s["rubric_element_id"], 0) + s["points"]
        if t in ("mcq", "multi"):
            n = [_exact(o) for o in p["options"]]
            assert len(set(n)) == len(n), (s["id"], "duplicate options")
            assert (3 <= len(n) <= 4) if t == "mcq" else len(n) >= 3, (s["id"], "option count")
        if t == "fill_blank":
            assert p["text"].count("____") == len(a["blanks"]), s["id"]
            bank = [_norm(b) for b in p["bank"]]
            for alts in a["blanks"]:
                assert any(_norm(x) in bank for x in alts), (s["id"], alts)
            assert len(set(bank)) == len(bank), (s["id"], "bank duplicates")
        if t == "matching":
            assert len(set(a["pairs"])) == len(a["pairs"]) == len(p["lefts"]), s["id"]
            assert len({_exact(r) for r in p["rights"]}) == len(p["rights"]), s["id"]
        if t == "ordering":
            assert len(set(p["items"])) == len(p["items"]), s["id"]
    for eid, mx in els.items():
        assert abs(got.get(eid, 0) - mx) < 1e-9, (eid, got.get(eid), mx)
    assert set(got) <= set(els), set(got) - set(els)
    assert abs(sum(qq["rubric_total"] for qq in Q) - 20) < 1e-9
    assert len({s["id"] for s in S}) == len(S)


_check()

